<?php
namespace App\Services;
use App\Models\{AccountMapping,ChartAccount,FiscalPeriod,JournalEntry,JournalLine,PlatformAuditLog}; use App\Support\Decimal; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str; use Illuminate\Validation\ValidationException;
final class AccountingService {
    public function post(array $data): JournalEntry { return DB::transaction(function() use ($data): JournalEntry { $tenant=$data['tenant_id']; $period=FiscalPeriod::where('tenant_id',$tenant)->where('id',$data['fiscal_period_id'])->lockForUpdate()->firstOrFail(); if($period->state!=='open') throw ValidationException::withMessages(['fiscal_period_id'=>['The fiscal period is closed.']]); if($existing=JournalEntry::where('tenant_id',$tenant)->where('idempotency_key',$data['idempotency_key'])->first()) return $existing->load('lines'); $debit='0.000000';$credit='0.000000';$valid=[]; foreach($data['lines'] as $line){$d=Decimal::normalize((string)($line['debit']??'0'));$c=Decimal::normalize((string)($line['credit']??'0'));if(Decimal::compare($d,'0')<0||Decimal::compare($c,'0')<0||Decimal::compare($d,'0')>0&&Decimal::compare($c,'0')>0||Decimal::compare($d,'0')===0&&Decimal::compare($c,'0')===0) throw ValidationException::withMessages(['lines'=>['Each line must contain either a positive debit or a positive credit.']]);$account=ChartAccount::where('tenant_id',$tenant)->whereKey($line['account_id'])->where('is_active',true)->firstOrFail();if($account->company_id!==null&&$account->company_id!==$data['company_id']) throw ValidationException::withMessages(['lines'=>['An account is outside the selected company scope.']]);$debit=Decimal::add($debit,$d);$credit=Decimal::add($credit,$c);$valid[]=['account'=>$account,'debit'=>$d,'credit'=>$c,'description'=>$line['description']??null];}if(count($valid)<2||Decimal::compare($debit,$credit)!==0) throw ValidationException::withMessages(['lines'=>['Journal entries must have at least two lines and equal total debits and credits.']]);$entry=JournalEntry::create(['tenant_id'=>$tenant,'company_id'=>$data['company_id'],'fiscal_period_id'=>$period->id,'currency_id'=>$data['currency_id'],'reversal_of_id'=>$data['reversal_of_id']??null,'created_by'=>$data['created_by'],'number'=>$data['number']??'JE-'.now()->format('Ym').'-'.Str::upper(Str::random(6)),'entry_date'=>$data['entry_date'],'state'=>'posted','source_type'=>$data['source_type']??null,'source_id'=>$data['source_id']??null,'idempotency_key'=>$data['idempotency_key'],'exchange_rate'=>Decimal::normalize((string)($data['exchange_rate']??'1'),12),'description'=>$data['description']??null,'posted_at'=>now()]);foreach($valid as $line){JournalLine::create(['tenant_id'=>$tenant,'journal_entry_id'=>$entry->id,'account_id'=>$line['account']->id,'company_id'=>$data['company_id'],'debit'=>$line['debit'],'credit'=>$line['credit'],'base_debit'=>Decimal::mul($line['debit'],(string)($data['exchange_rate']??'1')),'base_credit'=>Decimal::mul($line['credit'],(string)($data['exchange_rate']??'1')),'description'=>$line['description']]);}PlatformAuditLog::create(['actor_user_id'=>$data['created_by'],'tenant_id'=>$tenant,'action'=>'accounting.journal.posted','auditable_type'=>JournalEntry::class,'auditable_id'=>$entry->id,'metadata'=>['debit'=>$debit,'credit'=>$credit,'source_type'=>$data['source_type']??null]]);return $entry->load('lines'); }); }
    public function reverse(JournalEntry $entry,string $idempotency,string $actor): JournalEntry { abort_unless($entry->state==='posted',422,'Only posted entries can be reversed.');$lines=$entry->lines->map(fn($line)=>['account_id'=>$line->account_id,'debit'=>$line->credit,'credit'=>$line->debit,'description'=>'Reversal of '.$entry->number])->all();return $this->post(['tenant_id'=>$entry->tenant_id,'company_id'=>$entry->company_id,'fiscal_period_id'=>$entry->fiscal_period_id,'currency_id'=>$entry->currency_id,'created_by'=>$actor,'entry_date'=>now()->toDateString(),'reversal_of_id'=>$entry->id,'idempotency_key'=>$idempotency,'description'=>'Reversal of '.$entry->number,'exchange_rate'=>$entry->exchange_rate,'lines'=>$lines]); }
    public function trialBalance(string $tenantId,string $companyId,string $from,string $to): array { $rows=JournalLine::query()->select('account_id')->selectRaw('sum(base_debit) as debit_total, sum(base_credit) as credit_total')->where('tenant_id',$tenantId)->where('company_id',$companyId)->whereHas('entry',fn($q)=>$q->where('state','posted')->whereBetween('entry_date',[$from,$to]))->with('account')->groupBy('account_id')->get();return $rows->map(fn($row)=>['account_id'=>$row->account_id,'account'=>$row->account?->name,'account_type'=>$row->account?->type,'debit'=>Decimal::normalize((string)$row->debit_total),'credit'=>Decimal::normalize((string)$row->credit_total),'balance'=>Decimal::sub((string)$row->debit_total,(string)$row->credit_total)])->all(); }
}
